-- Module quizzes, certification exam and starter question bank (all editable in Content → Quizzes).
-- Questions only test what the lessons teach. Safe to re-run.

insert into public.quizzes (id, module_id, path_id, kind, title, pass_pct, max_attempts, cooldown_hours, questions_per_attempt, shuffle, published) values
('12000000-0000-4000-8000-000000000001', '11000000-0000-4000-8000-000000000001', null, 'module', 'About JD Foods quiz', 80, null, 1, 6, true, true),
('12000000-0000-4000-8000-000000000002', '11000000-0000-4000-8000-000000000002', null, 'module', 'Product Knowledge quiz', 80, null, 1, 6, true, true),
('12000000-0000-4000-8000-000000000003', '11000000-0000-4000-8000-000000000003', null, 'module', 'Customer Types quiz', 80, null, 1, 5, true, true),
('12000000-0000-4000-8000-000000000004', '11000000-0000-4000-8000-000000000004', null, 'module', 'Sales Scripts quiz', 80, null, 1, 6, true, true),
('12000000-0000-4000-8000-000000000005', '11000000-0000-4000-8000-000000000005', null, 'module', 'Objection Handling quiz', 80, null, 1, 6, true, true),
('12000000-0000-4000-8000-000000000006', '11000000-0000-4000-8000-000000000006', null, 'module', 'SOPs quiz', 80, null, 1, 5, true, true),
('12000000-0000-4000-8000-000000000007', null, '10000000-0000-4000-8000-000000000001', 'certification', 'New Hire Certification Exam', 80, 3, 24, 20, true, true)
on conflict (id) do nothing;

insert into public.questions (quiz_id, type, prompt, options, correct, model_answer, explanation, competency_tag, difficulty, status, source)
select q.quiz_id::uuid, q.type::public.question_type, q.prompt, q.options::jsonb, q.correct::jsonb, q.model_answer, q.explanation,
       q.tag, q.diff::public.difficulty, 'approved', 'manual'
from (values
-- ---------------------------------------------------------------- Module 1: About JD Foods
('12000000-0000-4000-8000-000000000001', 'mcq', 'From which three countries does JD Foods import products?',
 '[{"id":"a","text":"Thailand, China and Australia"},{"id":"b","text":"Japan, Korea and the USA"},{"id":"c","text":"Vietnam, Indonesia and Malaysia"},{"id":"d","text":"China, India and Australia"}]', '["a"]', null,
 'JD Foods sources imported products from Thailand, China and Australia.', 'company', 'easy'),
('12000000-0000-4000-8000-000000000001', 'multi', 'Which of these are JD Foods'' core values? Select all that apply.',
 '[{"id":"a","text":"Quality"},{"id":"b","text":"Innovation"},{"id":"c","text":"Integrity"},{"id":"d","text":"Win-win collaboration"},{"id":"e","text":"Lowest price at all costs"},{"id":"f","text":"Speed over accuracy"}]', '["a","b","c","d"]', null,
 'The four values are quality, innovation, integrity and win-win collaboration.', 'company', 'easy'),
('12000000-0000-4000-8000-000000000001', 'tf', 'If a customer asks something you don''t know, it is better to give your best guess than to risk losing the sale.',
 '[]', 'false', null,
 'Integrity: never invent facts. Say you will check, then follow up.', 'company', 'easy'),
('12000000-0000-4000-8000-000000000001', 'mcq', 'Which JD Foods brand is the beverage line for cafés and milk tea shops?',
 '[{"id":"a","text":"Arkadia"},{"id":"b","text":"ThyChef"},{"id":"c","text":"All Purpose"},{"id":"d","text":"JD Express"}]', '["a"]', null,
 'Arkadia covers premium syrups, chai and pyramid tea bags.', 'company', 'easy'),
('12000000-0000-4000-8000-000000000001', 'mcq', 'What does "win-win collaboration" look like in a sale?',
 '[{"id":"a","text":"Recommending the size and quantity that fit the customer''s volume, even if it is smaller"},{"id":"b","text":"Always selling the biggest pack"},{"id":"c","text":"Giving a discount on every order"},{"id":"d","text":"Only selling to big customers"}]', '["a"]', null,
 'A good sale is good for the customer too. That trust brings re-orders and referrals.', 'company', 'medium'),
('12000000-0000-4000-8000-000000000001', 'short', 'In your own words, what are JD Foods'' three main business activities?',
 '[]', null, 'It manufactures sauces and powders, distributes them to food businesses, and imports products (from Thailand, China and Australia).',
 'JD Foods is a manufacturer, distributor and importer.', 'company', 'easy'),
('12000000-0000-4000-8000-000000000001', 'mcq', 'A serious prospective distributor asks if they can have exclusive rights to their province. What do you do?',
 '[{"id":"a","text":"Promise exclusivity to close the deal"},{"id":"b","text":"Qualify the lead and bring in your manager, because territory needs approval"},{"id":"c","text":"Tell them distributors are not allowed"},{"id":"d","text":"Ignore the question"}]', '["b"]', null,
 'Territory and special terms need manager approval. Never promise them yourself.', 'company', 'medium'),
('12000000-0000-4000-8000-000000000001', 'tf', 'When presenting a business package, you may promise the customer how much they will earn.',
 '[]', 'false', null,
 'Never promise income. Share facts (price, contents, margin structure) and let them decide.', 'company', 'easy'),

-- ---------------------------------------------------------------- Module 2: Product Knowledge
('12000000-0000-4000-8000-000000000002', 'mcq', 'What pack size are ThyChef flavored powders sold in?',
 '[{"id":"a","text":"1 kg"},{"id":"b","text":"120 g"},{"id":"c","text":"250 ml"},{"id":"d","text":"5 kg"}]', '["a"]', null,
 'ThyChef flavored powders come in 1 kg packs.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'multi', 'Which of these are ThyChef flavored powder flavors? Select all that apply.',
 '[{"id":"a","text":"Cheese"},{"id":"b","text":"Barbecue"},{"id":"c","text":"Salted Egg"},{"id":"d","text":"Ghost Chili"},{"id":"e","text":"Matcha"},{"id":"f","text":"Ube"}]', '["a","b","c","d"]', null,
 'Flavors include Cheese, Barbecue, Hot & Spicy, Salted Egg and Ghost Chili.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'mcq', 'Which product fits a milk tea shop best?',
 '[{"id":"a","text":"Arkadia Premium Syrups"},{"id":"b","text":"ThyChef Breading Mix"},{"id":"c","text":"ThyChef Soup Powder"},{"id":"d","text":"ThyChef Marinade Powder"}]', '["a"]', null,
 'Arkadia syrups, chai and tea bags are made for cafés and milk tea shops.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'mcq', 'What size is the All Purpose Chili Garlic jar?',
 '[{"id":"a","text":"120 g"},{"id":"b","text":"1 kg"},{"id":"c","text":"500 g"},{"id":"d","text":"250 g"}]', '["a"]', null,
 'All Purpose Chili Garlic comes in a 120 g jar.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'mcq', 'Which flavors do ThyChef soup powders come in?',
 '[{"id":"a","text":"Chicken, Seafood and Noodle"},{"id":"b","text":"Beef, Pork and Mushroom"},{"id":"c","text":"Tomato, Corn and Pumpkin"},{"id":"d","text":"Chicken, Beef and Vegetable"}]', '["a"]', null,
 'Soup powders: Chicken, Seafood and Noodle.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'tf', 'If a product detail is still marked TODO, you can quote it to customers as long as it sounds right.',
 '[]', 'false', null,
 'TODO means not confirmed. Tell the customer you will check.', 'product', 'easy'),
('12000000-0000-4000-8000-000000000002', 'mcq', 'A chef doubts that a powdered breading mix can match his own recipe. What is the best response?',
 '[{"id":"a","text":"Offer a side-by-side demo or sample"},{"id":"b","text":"Argue that powders are always better"},{"id":"c","text":"Offer a big discount right away"},{"id":"d","text":"Say every chef uses it"}]', '["a"]', null,
 'Chefs believe what they taste. Prove it with a demo instead of arguing.', 'product', 'medium'),
('12000000-0000-4000-8000-000000000002', 'scenario', 'A fries cart owner says: "Bakit pa ako bibili ng flavored powder? Okay naman ang plain fries ko." What do you say?',
 '[]', null, 'Acknowledge politely. Ask about their volume or best sellers. Explain that offering flavors like cheese or BBQ from the same fries can attract more customers and raise the average order, with consistent taste every batch. Suggest a small, low-risk trial of one or two flavors. No false claims or pressure.',
 'Sell the benefit to their business (more flavors, more sales), then offer a low-risk trial.', 'value', 'medium'),

-- ---------------------------------------------------------------- Module 3: Customer Types
('12000000-0000-4000-8000-000000000003', 'mcq', 'Which buyer usually cares most about documents such as permits and FDA registration?',
 '[{"id":"a","text":"A school or office cafeteria purchasing officer"},{"id":"b","text":"A food cart owner"},{"id":"c","text":"A home cook"},{"id":"d","text":"A milk tea barista"}]', '["a"]', null,
 'Institutional buyers often need documents and supplier accreditation.', 'discovery', 'easy'),
('12000000-0000-4000-8000-000000000003', 'mcq', 'When is the best time to visit a restaurant?',
 '[{"id":"a","text":"Outside peak hours, around 2–4 PM"},{"id":"b","text":"During the lunch rush"},{"id":"c","text":"During the dinner rush"},{"id":"d","text":"Right at closing time"}]', '["a"]', null,
 'Visit when the owner or chef has time to talk.', 'opening', 'easy'),
('12000000-0000-4000-8000-000000000003', 'multi', 'What do distributors usually care about? Select all that apply.',
 '[{"id":"a","text":"Margins and price tiers"},{"id":"b","text":"Territory"},{"id":"c","text":"Minimum orders and payment terms"},{"id":"d","text":"The salesperson''s personal schedule"},{"id":"e","text":"The color of the delivery truck"}]', '["a","b","c"]', null,
 'Distributors focus on margins, territory, minimums, terms, delivery and support.', 'discovery', 'medium'),
('12000000-0000-4000-8000-000000000003', 'mcq', 'What is a typical concern of food stall and kiosk owners?',
 '[{"id":"a","text":"Low cost and small minimum orders"},{"id":"b","text":"Formal supplier accreditation"},{"id":"c","text":"Imported luxury packaging"},{"id":"d","text":"Annual contracts"}]', '["a"]', null,
 'Cash flow is tight for stalls. Start small and be clear on terms.', 'discovery', 'easy'),
('12000000-0000-4000-8000-000000000003', 'tf', 'Some franchise stalls must buy from head-office suppliers, so you should ask about this early.',
 '[]', 'true', null,
 'Ask early so you know who really decides.', 'discovery', 'easy'),
('12000000-0000-4000-8000-000000000003', 'mcq', 'Café owners often compare beverage suppliers based on…',
 '[{"id":"a","text":"Cost per cup"},{"id":"b","text":"The supplier''s office location"},{"id":"c","text":"How many salespeople the supplier has"},{"id":"d","text":"Packaging color"}]', '["a"]', null,
 'Know the cost per cup and compare with facts only.', 'value', 'medium'),
('12000000-0000-4000-8000-000000000003', 'short', 'Name two things a school cafeteria buyer usually cares about.',
 '[]', null, 'Any two of: consistency and food safety; documents (permits, FDA registration, accreditation); stable price and reliable supply for the term; proper invoicing and payment terms.',
 'Cafeterias need consistency, documents, reliable supply and proper invoicing.', 'discovery', 'easy'),

-- ---------------------------------------------------------------- Module 4: Sales Scripts
('12000000-0000-4000-8000-000000000004', 'mcq', 'What is the main goal of a cold call?',
 '[{"id":"a","text":"Earn a next step such as a visit or sampling"},{"id":"b","text":"Close a big order immediately"},{"id":"c","text":"Read the whole price list"},{"id":"d","text":"Find out the competitor''s prices"}]', '["a"]', null,
 'On a first call, aim for a next step, not a big order.', 'opening', 'easy'),
('12000000-0000-4000-8000-000000000004', 'mcq', 'The customer on a cold call says they are busy. What is the best reply?',
 '[{"id":"a","text":"\"Naiintindihan ko po. Kailan po magandang tumawag ulit, mamayang hapon o bukas ng umaga?\""},{"id":"b","text":"Keep talking quickly"},{"id":"c","text":"Hang up without saying anything"},{"id":"d","text":"\"Sige po, bye.\""}]', '["a"]', null,
 'Respect their time and secure a specific callback time with two choices.', 'opening', 'easy'),
('12000000-0000-4000-8000-000000000004', 'tf', 'When asking for a next step, offering two choices ("Tuesday or Thursday?") usually works better than a yes/no question.',
 '[]', 'true', null,
 'Two choices make it easy to say yes to one of them.', 'closing', 'easy'),
('12000000-0000-4000-8000-000000000004', 'mcq', 'Which of these is a choice close?',
 '[{"id":"a","text":"\"Gusto po ba ninyong magsimula sa 3 kilos o sa 5 kilos?\""},{"id":"b","text":"\"Ano pong masasabi ninyo?\""},{"id":"c","text":"\"Salamat po sa oras ninyo.\""},{"id":"d","text":"\"May tanong pa po ba kayo?\""}]', '["a"]', null,
 'A choice close offers two options that both mean yes.', 'closing', 'easy'),
('12000000-0000-4000-8000-000000000004', 'mcq', 'A stall sells a lot of cheese fries. Which is the most natural cross-sell?',
 '[{"id":"a","text":"Dipping cheese powder"},{"id":"b","text":"Soup powder"},{"id":"c","text":"Pyramid tea bags"},{"id":"d","text":"Marinade powder"}]', '["a"]', null,
 'A cheese dip upgrade fits what they already sell.', 'value', 'easy'),
('12000000-0000-4000-8000-000000000004', 'mcq', 'A regular customer misses their usual re-order date. What should you do?',
 '[{"id":"a","text":"Call them. They might be switching suppliers"},{"id":"b","text":"Wait until they call you"},{"id":"c","text":"Remove them from your list"},{"id":"d","text":"Send a bigger order anyway"}]', '["a"]', null,
 'A late re-order can be an early warning. Reach out early.', 'closing', 'medium'),
('12000000-0000-4000-8000-000000000004', 'tf', 'After you ask for the order, keep talking so there is no awkward silence.',
 '[]', 'false', null,
 'Ask, then stay quiet and let the customer answer.', 'closing', 'medium'),
('12000000-0000-4000-8000-000000000004', 'scenario', 'You walk into a carinderia during a quiet afternoon. Write your opening, the first two or three lines you would say.',
 '[]', null, 'Greets politely, asks for the owner or person in charge, introduces own name and JD Foods in one short sentence, makes a genuine compliment or observation about the business, and asks an open question about their business (for example best sellers). Taglish with "po" is fine. Does not jump straight into a hard pitch.',
 'Greet, introduce, compliment, then ask a question. Pitch only after you understand their needs.', 'opening', 'medium'),

-- ---------------------------------------------------------------- Module 5: Objection Handling
('12000000-0000-4000-8000-000000000005', 'mcq', 'What does LAER stand for?',
 '[{"id":"a","text":"Listen, Acknowledge, Explore, Respond"},{"id":"b","text":"Look, Ask, Explain, Repeat"},{"id":"c","text":"Listen, Argue, Explain, Resolve"},{"id":"d","text":"Learn, Agree, Engage, Return"}]', '["a"]', null,
 'LAER: Listen, Acknowledge, Explore, Respond.', 'objections', 'easy'),
('12000000-0000-4000-8000-000000000005', 'mcq', 'What does "acknowledge" mean in LAER?',
 '[{"id":"a","text":"Showing you understand the concern, without necessarily agreeing"},{"id":"b","text":"Agreeing that the customer is right"},{"id":"c","text":"Giving a discount"},{"id":"d","text":"Repeating your pitch"}]', '["a"]', null,
 '"Naiintindihan ko po" shows understanding. It is not agreement.', 'objections', 'easy'),
('12000000-0000-4000-8000-000000000005', 'tf', 'When a customer says a competitor is cheaper, you should point out the competitor''s weaknesses.',
 '[]', 'false', null,
 'Never badmouth competitors. Talk about your value.', 'objections', 'easy'),
('12000000-0000-4000-8000-000000000005', 'mcq', 'For "mas mura sa iba", what should your answer focus on?',
 '[{"id":"a","text":"Value, such as cost per serving, consistency and sales impact"},{"id":"b","text":"An immediate discount"},{"id":"c","text":"How expensive your own costs are"},{"id":"d","text":"Ending the conversation"}]', '["a"]', null,
 'Compare value, not just the pack price.', 'objections', 'medium'),
('12000000-0000-4000-8000-000000000005', 'mcq', 'A customer says "May supplier na kami." What is a good first goal?',
 '[{"id":"a","text":"Become their backup or second option"},{"id":"b","text":"Convince them to drop their supplier today"},{"id":"c","text":"Criticize their supplier"},{"id":"d","text":"Leave immediately"}]', '["a"]', null,
 'Respect their loyalty and position yourself as the backup first.', 'objections', 'medium'),
('12000000-0000-4000-8000-000000000005', 'mcq', 'The customer says "Pag-iisipan ko muna." What is the best response?',
 '[{"id":"a","text":"Ask what specifically they want to think about, offer a low-risk step, and agree on a specific follow-up"},{"id":"b","text":"\"Sige po, balitaan n''yo na lang ako.\""},{"id":"c","text":"Push harder until they agree"},{"id":"d","text":"Offer the biggest discount you can"}]', '["a"]', null,
 'Find the hidden concern and never leave without a specific next step.', 'objections', 'medium'),
('12000000-0000-4000-8000-000000000005', 'tf', 'To win a new account, you may agree to 30-day payment terms on the spot.',
 '[]', 'false', null,
 'Payment terms are company policy. Check with your manager for special requests.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000005', 'scenario', 'A carinderia owner tells you: "Mas mura yung chili garlic na gamit ko ngayon." How do you respond?',
 '[]', null, 'Listens and acknowledges without arguing. Explores what they pay now and how fast they use it. Responds with value: taste and consistency, cost per serving, customer satisfaction. Offers a small trial or side-by-side test. Does not badmouth the competitor or promise an unapproved discount. Asks for a next step.',
 'Use LAER: acknowledge, explore their current cost and usage, then show value and offer a low-risk trial.', 'objections', 'medium'),

-- ---------------------------------------------------------------- Module 6: SOPs
('12000000-0000-4000-8000-000000000006', 'mcq', 'What is the last step when taking an order?',
 '[{"id":"a","text":"Read the order back and get the customer''s confirmation"},{"id":"b","text":"Ask for a referral"},{"id":"c","text":"Offer a discount"},{"id":"d","text":"Leave quickly"}]', '["a"]', null,
 'Reading the order back prevents costly mistakes.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000006', 'tf', 'If you are sure of a price, you may quote it from memory instead of the current price list.',
 '[]', 'false', null,
 'Always quote from the current official price list.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000006', 'mcq', 'A customer asks for a special price beyond your approval limit. What do you do?',
 '[{"id":"a","text":"Get the details (volume, frequency, competitor price) and bring it to your manager"},{"id":"b","text":"Agree to it to close the sale"},{"id":"c","text":"Refuse and end the conversation"},{"id":"d","text":"Tell them prices never change"}]', '["a"]', null,
 'Collect the facts and escalate. Never promise discounts you can''t give.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000006', 'mcq', 'A delivery is going to be late. What should happen?',
 '[{"id":"a","text":"The customer hears it from you first, with a new date"},{"id":"b","text":"Say nothing and hope they don''t notice"},{"id":"c","text":"Blame the warehouse"},{"id":"d","text":"Cancel the order"}]', '["a"]', null,
 'Tell them early and honestly, with a new date.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000006', 'multi', 'What should you record after every customer contact? Select all that apply.',
 '[{"id":"a","text":"Who you talked to and when"},{"id":"b","text":"Their needs and the products discussed"},{"id":"c","text":"Objections raised"},{"id":"d","text":"The agreed next step and date"},{"id":"e","text":"What you had for lunch"}]', '["a","b","c","d"]', null,
 'Good records let your manager help you and keep customers from being forgotten.', 'sop', 'easy'),
('12000000-0000-4000-8000-000000000006', 'mcq', 'A customer says a product arrived damaged. Before a return is approved, you should…',
 '[{"id":"a","text":"Get the details (product, batch/expiry, quantity, photos) and not promise a refund until it is approved"},{"id":"b","text":"Promise a full refund immediately"},{"id":"c","text":"Tell them it is their fault"},{"id":"d","text":"Ignore it"}]', '["a"]', null,
 'Collect details, stay calm and follow the approval steps.', 'sop', 'medium'),
('12000000-0000-4000-8000-000000000006', 'tf', 'Payments you collect should be recorded on the same day.',
 '[]', 'true', null,
 'Record every collection the same day.', 'sop', 'easy'),

-- ---------------------------------------------------------------- Certification-only scenarios
('12000000-0000-4000-8000-000000000007', 'scenario', 'A school cafeteria purchasing officer asks: "Do you have FDA documents, and can you guarantee supply for the whole school year?" How do you respond?',
 '[]', null, 'Acknowledges that documents and supply matter. Is honest: offers to provide the documents JD Foods actually has, and confirms rather than guesses anything uncertain. Explains supply and lead times only as far as known. Asks about their volume and menu cycle. Agrees a concrete next step (send documents, meeting date). Shows integrity and no overpromising.',
 'Institutional buyers value honesty, documents and reliability. Never promise what you can''t confirm.', 'product', 'hard'),
('12000000-0000-4000-8000-000000000007', 'scenario', 'A milk tea shop owner says: "Bakit pa ako lilipat sa Arkadia? Okay naman ang syrups ko ngayon." What do you say?',
 '[]', null, 'Respects the current supplier without attacking it. Asks what they like or dislike and what their top sellers are. Suggests Arkadia as a backup or for a new flavor or menu item. Compares cost per cup with facts only. Offers a tasting or sample and asks for a next step.',
 'Aim to be their second option first; prove value with a tasting.', 'objections', 'hard'),
('12000000-0000-4000-8000-000000000007', 'scenario', 'A restaurant chef says: "Hindi ako gumagamit ng powdered breading. Mas masarap ang sariling timpla ko." How do you respond?',
 '[]', null, 'Respects the chef''s expertise. Explores what they value (taste, texture, consistency). Offers a side-by-side demo, ideally with their own staff cooking. Mentions consistency across cooks and less prep time without exaggerating. Asks for a demo date.',
 'Don''t argue with a chef. Let the food prove it in a side-by-side test.', 'objections', 'hard'),
('12000000-0000-4000-8000-000000000007', 'scenario', 'A regular customer calls, upset: "Late na naman ang delivery ninyo! Paano ako magbebenta?" How do you handle it?',
 '[]', null, 'Listens fully, apologizes sincerely without blaming others, and gets the order details. Gives an honest update or new delivery time only if confirmed, or commits to call back by a specific time. Offers a fix or escalates to the manager. Follows up and thanks the customer, then confirms their next re-order once resolved.',
 'Recovery: listen, apologize, act, follow up. Keep the relationship first.', 'communication', 'hard')
) as q(quiz_id, type, prompt, options, correct, model_answer, explanation, tag, diff)
where not exists (select 1 from public.questions x where x.quiz_id = q.quiz_id::uuid);
